//! Precomputed tables and constants.
//!
//! Generated by `tools/gen-tables` with exact integer arithmetic. Do not edit
//! by hand: CI regenerates them and fails on any diff.

macro_rules! define_consts {
    ($T:ident { $($name:ident = $raw:literal, $doc:literal;)* }) => {
        impl crate::$T {
            $(
                #[doc = concat!($doc, ", correctly rounded to nearest.")]
                pub const $name: Self = Self::from_bits($raw);
            )*
        }
    };
}

mod consts;
